import { Node, Vec3, Color, Quat } from 'cc';
import { createPrimitiveNode, Palette } from '../core/PrimitiveFactory';

// Builds a medieval-style 3D environment procedurally using primitives.
// Returns the root world node. Player ground plane at y=0.
export function buildWorld(): Node {
    const root = new Node('World');

    // === GROUND ===
    const ground = createPrimitiveNode('Ground', 'box', new Vec3(220, 0.5, 220), Palette.grass);
    ground.setPosition(0, -0.25, 0);
    root.addChild(ground);

    // Patches of darker grass / dirt for visual variety
    for (let i = 0; i < 40; i++) {
        const ang = Math.random() * Math.PI * 2;
        const r = 20 + Math.random() * 80;
        const x = Math.cos(ang) * r, z = Math.sin(ang) * r;
        const size = 4 + Math.random() * 8;
        const c = Math.random() < 0.5 ? Palette.grassDark : Palette.dirt;
        const patch = createPrimitiveNode('Patch', 'box', new Vec3(size, 0.06, size), c);
        patch.setPosition(x, 0.01, z);
        patch.setRotationFromEuler(0, Math.random() * 360, 0);
        root.addChild(patch);
    }

    // === VILLAGE (center) ===
    const village = new Node('Village');
    root.addChild(village);

    // Village square stone platform
    const square = createPrimitiveNode('Square', 'cylinder', new Vec3(14, 0.2, 14), Palette.stone);
    square.setPosition(0, 0.05, 6);
    village.addChild(square);

    // Houses around the village
    const housePositions: { x: number; z: number; rot: number }[] = [
        { x: -10, z: 12, rot: 25 },
        { x:  10, z: 12, rot: -25 },
        { x: -12, z:  0, rot: 90 },
        { x:  12, z:  0, rot: -90 },
        { x:   0, z: 16, rot: 0 },
    ];
    for (const h of housePositions) village.addChild(buildHouse(h.x, h.z, h.rot));

    // Central well
    village.addChild(buildWell(0, 6));

    // Lampposts (torches)
    const lampSpots = [[-7, 6], [7, 6], [-7, 14], [7, 14], [0, 0]];
    for (const [x, z] of lampSpots) village.addChild(buildTorch(x, z));

    // Village wall (low fence)
    const wallPieces = 18;
    for (let i = 0; i < wallPieces; i++) {
        const t = i / wallPieces * Math.PI * 2;
        const r = 17;
        const x = Math.cos(t) * r, z = 6 + Math.sin(t) * r;
        // Skip wall on south side to create entrance
        if (Math.abs(x) < 4 && z < 0) continue;
        const post = createPrimitiveNode('Fence', 'box', new Vec3(0.4, 1.2, 0.4), Palette.woodDark);
        post.setPosition(x, 0.6, z);
        post.setRotationFromEuler(0, t * 180 / Math.PI, 0);
        village.addChild(post);
    }

    // === FOREST ZONES ===
    // North-west forest
    spawnTreeCluster(root, -55, 30, 14, 22);
    // North-east forest
    spawnTreeCluster(root,  55, 30, 14, 22);
    // South forest
    spawnTreeCluster(root,   0, -50, 18, 30);
    // Far west/east clumps
    spawnTreeCluster(root, -70, -20, 10, 14);
    spawnTreeCluster(root,  70, -20, 10, 14);

    // === ROCK FORMATIONS ===
    spawnRocks(root, -45, -45, 12);
    spawnRocks(root,  45, -45, 12);
    spawnRocks(root, -45,  45, 10);
    spawnRocks(root,  45,  45, 10);
    spawnRocks(root,   0, -85, 8);

    // === RUINS (where skeletons spawn) ===
    root.addChild(buildRuins(-40, 40));

    // === LAKE / WATER ===
    const lake = createPrimitiveNode('Lake', 'cylinder', new Vec3(18, 0.15, 18), Palette.water);
    lake.setPosition(-65, 0.02, 60);
    root.addChild(lake);

    // === ROADS (dirt paths from village to each zone) ===
    const roadDirs = [
        { ang: 225, len: 70 },
        { ang: 315, len: 70 },
        { ang: 135, len: 70 },
        { ang:  45, len: 70 },
        { ang: 270, len: 70 },
    ];
    for (const r of roadDirs) {
        const rad = r.ang * Math.PI / 180;
        const segs = 14;
        for (let i = 1; i <= segs; i++) {
            const d = (i / segs) * r.len;
            const x = Math.cos(rad) * d;
            const z = 6 + Math.sin(rad) * d;
            const tile = createPrimitiveNode('Road', 'box', new Vec3(2.5, 0.05, 2.5), Palette.dirt);
            tile.setPosition(x, 0.02, z);
            root.addChild(tile);
        }
    }

    // === SKYBOX-LIKE BACKGROUND CYLINDER (distant mountains) ===
    for (let i = 0; i < 20; i++) {
        const ang = (i / 20) * Math.PI * 2;
        const x = Math.cos(ang) * 110, z = 6 + Math.sin(ang) * 110;
        const h = 12 + Math.random() * 14;
        const mtn = createPrimitiveNode('Mountain', 'cone', new Vec3(14, h, 14), Palette.stoneDark);
        mtn.setPosition(x, h / 2, z);
        root.addChild(mtn);
    }

    return root;
}

function buildHouse(x: number, z: number, rotY = 0): Node {
    const house = new Node('House');
    house.setPosition(x, 0, z);
    house.setRotationFromEuler(0, rotY, 0);

    // Wooden walls
    const walls = createPrimitiveNode('Walls', 'box', new Vec3(4, 3, 4), Palette.wood);
    walls.setPosition(0, 1.5, 0);
    house.addChild(walls);

    // Wood beams (cross pattern decoration)
    const beam1 = createPrimitiveNode('Beam1', 'box', new Vec3(4.1, 0.2, 0.2), Palette.woodDark);
    beam1.setPosition(0, 2.5, 2.05); house.addChild(beam1);
    const beam2 = createPrimitiveNode('Beam2', 'box', new Vec3(0.2, 3, 0.2), Palette.woodDark);
    beam2.setPosition(-1.5, 1.5, 2.05); house.addChild(beam2);
    const beam3 = createPrimitiveNode('Beam3', 'box', new Vec3(0.2, 3, 0.2), Palette.woodDark);
    beam3.setPosition(1.5, 1.5, 2.05); house.addChild(beam3);

    // Roof (pyramid)
    const roof = createPrimitiveNode('Roof', 'cone', new Vec3(5.5, 2.2, 5.5), Palette.roof);
    roof.setPosition(0, 4.1, 0);
    house.addChild(roof);

    // Door
    const door = createPrimitiveNode('Door', 'box', new Vec3(0.8, 1.6, 0.1), Palette.woodDark);
    door.setPosition(0, 0.8, 2.05);
    house.addChild(door);

    // Window
    const win = createPrimitiveNode('Window', 'box', new Vec3(0.6, 0.6, 0.1), new Color(120, 180, 220));
    win.setPosition(1.3, 2, 2.05);
    house.addChild(win);

    // Chimney
    const chim = createPrimitiveNode('Chimney', 'box', new Vec3(0.6, 1.8, 0.6), Palette.stone);
    chim.setPosition(1.2, 4.5, -1.2);
    house.addChild(chim);

    return house;
}

function buildWell(x: number, z: number): Node {
    const well = new Node('Well');
    well.setPosition(x, 0, z);
    const base = createPrimitiveNode('WellBase', 'cylinder', new Vec3(1.6, 1, 1.6), Palette.stone);
    base.setPosition(0, 0.5, 0); well.addChild(base);
    const water = createPrimitiveNode('Water', 'cylinder', new Vec3(1.3, 0.05, 1.3), Palette.water);
    water.setPosition(0, 1.01, 0); well.addChild(water);
    const post1 = createPrimitiveNode('Post1', 'box', new Vec3(0.18, 2, 0.18), Palette.wood);
    post1.setPosition(-0.9, 2, 0); well.addChild(post1);
    const post2 = createPrimitiveNode('Post2', 'box', new Vec3(0.18, 2, 0.18), Palette.wood);
    post2.setPosition(0.9, 2, 0); well.addChild(post2);
    const top = createPrimitiveNode('Top', 'box', new Vec3(2.2, 0.15, 1.4), Palette.roof);
    top.setPosition(0, 3.05, 0); well.addChild(top);
    return well;
}

function buildTorch(x: number, z: number): Node {
    const t = new Node('Torch');
    t.setPosition(x, 0, z);
    const pole = createPrimitiveNode('Pole', 'cylinder', new Vec3(0.15, 2.4, 0.15), Palette.woodDark);
    pole.setPosition(0, 1.2, 0); t.addChild(pole);
    const flame = createPrimitiveNode('Flame', 'sphere', new Vec3(0.45, 0.45, 0.45), new Color(255, 160, 50));
    flame.setPosition(0, 2.6, 0); t.addChild(flame);
    return t;
}

function spawnTreeCluster(root: Node, cx: number, cz: number, count: number, radius: number) {
    for (let i = 0; i < count; i++) {
        const ang = Math.random() * Math.PI * 2;
        const r = Math.random() * radius;
        const x = cx + Math.cos(ang) * r;
        const z = cz + Math.sin(ang) * r;
        root.addChild(buildTree(x, z));
    }
}

function buildTree(x: number, z: number): Node {
    const t = new Node('Tree');
    t.setPosition(x, 0, z);
    const trunk = createPrimitiveNode('Trunk', 'cylinder', new Vec3(0.6, 3, 0.6), Palette.woodDark);
    trunk.setPosition(0, 1.5, 0); t.addChild(trunk);
    const leaves1 = createPrimitiveNode('Leaves1', 'sphere', new Vec3(2.8, 2.8, 2.8), Palette.grassDark);
    leaves1.setPosition(0, 3.6, 0); t.addChild(leaves1);
    const leaves2 = createPrimitiveNode('Leaves2', 'sphere', new Vec3(2.2, 2.2, 2.2), Palette.grass);
    leaves2.setPosition(0.4, 4.4, 0.3); t.addChild(leaves2);
    return t;
}

function spawnRocks(root: Node, cx: number, cz: number, count: number) {
    for (let i = 0; i < count; i++) {
        const ang = Math.random() * Math.PI * 2;
        const r = Math.random() * 14;
        const x = cx + Math.cos(ang) * r;
        const z = cz + Math.sin(ang) * r;
        const s = 0.6 + Math.random() * 1.8;
        const color = Math.random() < 0.5 ? Palette.stone : Palette.stoneDark;
        const rock = createPrimitiveNode('Rock', 'sphere', new Vec3(s, s * 0.7, s), color);
        rock.setPosition(x, s * 0.3, z);
        rock.setRotationFromEuler(Math.random() * 360, Math.random() * 360, Math.random() * 360);
        root.addChild(rock);
    }
}

function buildRuins(x: number, z: number): Node {
    const r = new Node('Ruins');
    r.setPosition(x, 0, z);
    const floor = createPrimitiveNode('RuinFloor', 'box', new Vec3(10, 0.2, 10), Palette.stoneDark);
    floor.setPosition(0, 0.1, 0); r.addChild(floor);

    // Broken pillars at corners
    const corners = [[-4, -4], [4, -4], [-4, 4], [4, 4]];
    for (const [cx, cz] of corners) {
        const h = 2 + Math.random() * 2;
        const pillar = createPrimitiveNode('Pillar', 'cylinder', new Vec3(0.8, h, 0.8), Palette.stone);
        pillar.setPosition(cx, h / 2, cz); r.addChild(pillar);
    }
    // A broken arch
    const archL = createPrimitiveNode('ArchL', 'box', new Vec3(0.7, 3, 0.7), Palette.stone);
    archL.setPosition(-1.5, 1.5, 0); r.addChild(archL);
    const archR = createPrimitiveNode('ArchR', 'box', new Vec3(0.7, 3, 0.7), Palette.stone);
    archR.setPosition(1.5, 1.5, 0); r.addChild(archR);
    const archTop = createPrimitiveNode('ArchTop', 'box', new Vec3(3.7, 0.6, 0.7), Palette.stone);
    archTop.setPosition(0, 3.3, 0); r.addChild(archTop);

    return r;
}